import { useState } from "react";
import { useNavigate } from "react-router-dom";
import {
  Minus, Plus, Trash2, ShoppingBag, ArrowRight,
  Tag, Truck, Shield, Package, Store,
} from "lucide-react";

interface CartItem {
  productId: string;
  productName: string;
  vendorName: string;
  quantity: number;
  price: number;
  image?: string;
}

const mockItems: CartItem[] = [
  { productId: "1", productName: "ওয়্যারলেস হেডফোন প্রো", vendorName: "TechZone BD", quantity: 1, price: 1299, image: "https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=200&h=200&fit=crop" },
  { productId: "2", productName: "কোরিয়ান সিল্ক শাড়ি",   vendorName: "Fashion Hub",  quantity: 2, price: 3500, image: "https://images.unsplash.com/photo-1523381210434-271e8be1f52b?w=200&h=200&fit=crop" },
];

export default function Cart() {
  const navigate = useNavigate();
  const [items, setItems] = useState<CartItem[]>(mockItems);

  const updateQuantity = (id: string, qty: number) => {
    if (qty < 1) return;
    setItems(prev => prev.map(i => i.productId === id ? { ...i, quantity: qty } : i));
  };

  const removeItem = (id: string) => {
    setItems(prev => prev.filter(i => i.productId !== id));
  };

  const totalPrice  = items.reduce((sum, i) => sum + i.price * i.quantity, 0);
  const delivery    = items.length > 0 ? 60 : 0;
  const grandTotal  = totalPrice + delivery;

  return (
    <div className="px-4 pt-4">
      <h1 className="text-xl font-bold mb-1" style={{ color: "var(--pm-text)" }}>শপিং কার্ট</h1>
      <p className="text-sm mb-5" style={{ color: "var(--pm-text-muted)" }}>
        {items.length}টি পণ্য আপনার কার্টে আছে
      </p>

      {items.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-20 text-center">
          <div
            className="h-24 w-24 rounded-full flex items-center justify-center mb-6 border"
            style={{ background: "var(--pm-accent-soft)", borderColor: "var(--pm-accent)" }}
          >
            <ShoppingBag className="h-12 w-12" style={{ color: "var(--pm-accent)" }} />
          </div>
          <h2 className="text-xl font-semibold mb-2" style={{ color: "var(--pm-text)" }}>
            কার্ট খালি আছে
          </h2>
          <p className="mb-6" style={{ color: "var(--pm-text-muted)" }}>
            পণ্য যোগ করুন এবং কেনাকাটা শুরু করুন
          </p>
          <button
            onClick={() => navigate("/shop")}
            className="px-6 py-3 rounded-xl font-semibold text-white"
            style={{ background: "var(--pm-accent)" }}
          >
            শপিং করুন
          </button>
        </div>
      ) : (
        <div className="flex flex-col gap-4">
          {/* Items */}
          <div className="space-y-3">
            {items.map(item => (
              <div
                key={item.productId}
                className="rounded-xl overflow-hidden border p-4"
                style={{ background: "var(--pm-surface)", borderColor: "var(--pm-border)" }}
              >
                <div className="flex gap-4">
                  <div className="h-24 w-24 rounded-xl overflow-hidden shrink-0 border" style={{ borderColor: "var(--pm-border)" }}>
                    {item.image ? (
                      <img src={item.image} alt={item.productName} className="w-full h-full object-cover" />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center" style={{ background: "var(--pm-surface)" }}>
                        <Package className="h-8 w-8" style={{ color: "var(--pm-text-muted)" }} />
                      </div>
                    )}
                  </div>

                  <div className="flex-1 flex flex-col justify-between min-w-0">
                    <div className="flex justify-between gap-2">
                      <div className="min-w-0">
                        <h3 className="font-semibold text-sm line-clamp-2" style={{ color: "var(--pm-text)" }}>
                          {item.productName}
                        </h3>
                        <p className="text-xs mt-0.5 flex items-center gap-1" style={{ color: "var(--pm-text-muted)" }}>
                          <Store className="h-3 w-3" /> {item.vendorName}
                        </p>
                      </div>
                      <div className="text-right shrink-0">
                        <div className="font-bold" style={{ color: "var(--pm-text)" }}>
                          ৳{(item.price * item.quantity).toLocaleString()}
                        </div>
                        <div className="text-xs" style={{ color: "var(--pm-text-muted)" }}>
                          ৳{item.price.toLocaleString()} প্রতিটি
                        </div>
                      </div>
                    </div>

                    <div className="flex items-center justify-between mt-3">
                      {/* Quantity */}
                      <div
                        className="flex items-center gap-0.5 rounded-lg overflow-hidden border"
                        style={{ background: "var(--pm-surface)", borderColor: "var(--pm-border)" }}
                      >
                        <button
                          onClick={() => updateQuantity(item.productId, item.quantity - 1)}
                          className="h-8 w-8 flex items-center justify-center transition-colors hover:bg-white/10"
                          style={{ color: "var(--pm-text-muted)" }}
                        >
                          <Minus className="h-3.5 w-3.5" />
                        </button>
                        <span className="w-10 text-center text-sm font-semibold" style={{ color: "var(--pm-text)" }}>
                          {item.quantity}
                        </span>
                        <button
                          onClick={() => updateQuantity(item.productId, item.quantity + 1)}
                          className="h-8 w-8 flex items-center justify-center transition-colors hover:bg-white/10"
                          style={{ color: "var(--pm-text-muted)" }}
                        >
                          <Plus className="h-3.5 w-3.5" />
                        </button>
                      </div>

                      <button
                        onClick={() => removeItem(item.productId)}
                        className="flex items-center gap-1 text-xs text-red-400 hover:text-red-300 transition-colors"
                      >
                        <Trash2 className="h-3.5 w-3.5" /> সরান
                      </button>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>

          {/* Order Summary */}
          <div
            className="rounded-xl border p-5"
            style={{ background: "var(--pm-surface)", borderColor: "var(--pm-border)" }}
          >
            <h2 className="text-lg font-bold mb-4" style={{ color: "var(--pm-text)" }}>
              অর্ডার সারসংক্ষেপ
            </h2>

            <div className="space-y-3 mb-4">
              <div className="flex justify-between text-sm">
                <span style={{ color: "var(--pm-text-muted)" }}>মোট ({items.length}টি পণ্য)</span>
                <span className="font-medium" style={{ color: "var(--pm-text)" }}>৳{totalPrice.toLocaleString()}</span>
              </div>
              <div className="flex justify-between text-sm">
                <span className="flex items-center gap-1.5" style={{ color: "var(--pm-text-muted)" }}>
                  <Truck className="h-3.5 w-3.5" /> ডেলিভারি চার্জ
                </span>
                <span className="font-medium" style={{ color: "var(--pm-text)" }}>৳{delivery}</span>
              </div>
            </div>

            <div className="border-t pt-4 mb-4" style={{ borderColor: "var(--pm-border)" }}>
              <div className="flex justify-between font-bold">
                <span style={{ color: "var(--pm-text)" }}>সর্বমোট</span>
                <span className="text-xl" style={{ color: "var(--pm-accent)" }}>
                  ৳{grandTotal.toLocaleString()}
                </span>
              </div>
            </div>

            <button
              onClick={() => navigate("/checkout")}
              className="w-full py-3 rounded-xl font-semibold text-white flex items-center justify-center gap-2 transition-all hover:opacity-90"
              style={{ background: "var(--pm-accent)" }}
            >
              চেকআউট করুন <ArrowRight className="h-4 w-4" />
            </button>
          </div>

          {/* Trust Badges */}
          <div
            className="rounded-xl border p-4 space-y-3"
            style={{ background: "var(--pm-surface)", borderColor: "var(--pm-border)" }}
          >
            {[
              { icon: Truck,  text: "সারা বাংলাদেশে দ্রুত ডেলিভারি", color: "var(--pm-accent)" },
              { icon: Shield, text: "নিরাপদ ও এনক্রিপ্টেড চেকআউট",  color: "#60a5fa" },
              { icon: Tag,    text: "সর্বোত্তম মূল্য নিশ্চিত",         color: "#a78bfa" },
            ].map(({ icon: Icon, text, color }) => (
              <div key={text} className="flex items-center gap-3">
                <div
                  className="h-8 w-8 rounded-full flex items-center justify-center shrink-0"
                  style={{ background: "var(--pm-accent-soft)" }}
                >
                  <Icon className="h-4 w-4" style={{ color }} />
                </div>
                <span className="text-sm" style={{ color: "var(--pm-text-muted)" }}>{text}</span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}